// Krasnov : place de l'Ours et immeuble à écriteaux dans la rue de la mairie.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const root=new URL('../../',import.meta.url),read=p=>fs.readFileSync(new URL(p,root),'utf8');
const rue=read('plateau-rue-centrale.js');
const start=rue.indexOf("'krasnov-rue-mairie-place':"),end=rue.indexOf("'krasnov-rue-tabac-bar':",start);
assert.ok(start>=0&&end>start);
const scene=rue.slice(start,end);
assert.match(scene,/gauche: 'krasnov-place-ours'/);
assert.match(scene,/arriere: 'krasnov-rue-immeubles-centre-commercial'/);
assert.match(scene,/toutDroit: 'krasnov-rue-tabac-bar'/);
assert.match(scene,/buildingId: 'logements-krasnov-place-ours'/);
assert.match(scene,/xPct: \[54, 71\]/);
assert.match(scene,/'krasnov-place-ours':/);
assert.match(scene,/image: 'images\/Sovarka\/Krasnov\/Krasnov_place_ours.webp'/);
assert.match(scene,/nom: 'Mairie de Krasnov', type: 'batiment', buildingId: 'mairie'/);
assert.match(scene,/liens: \{ arriere: 'krasnov-rue-mairie-place' \}/);
const b=fs.readFileSync(new URL('images/Sovarka/Krasnov/Krasnov_place_ours.webp',root));
assert.equal(b.toString('ascii',0,4),'RIFF');
assert.equal(b.toString('ascii',8,12),'WEBP');
assert.equal(fs.readdirSync(new URL('images/',root)).filter(x=>x.startsWith('Place sovi')&&x.endsWith('.png')).length,0);
const ctx=vm.createContext({});
vm.runInContext(read('data.js'),ctx);
assert.ok(vm.runInContext("WORLD.soviet.ville_b.buildings.includes('logements-krasnov-place-ours')",ctx));
assert.equal(vm.runInContext("Object.keys(BUILDINGS['logements-krasnov-place-ours'].rooms).length",ctx),9);
assert.equal(vm.runInContext("BUILDINGS['logements-krasnov-place-ours'].rooms.hall.orders.length",ctx),0);
const sql=read('migrations/20261114194500_krasnov_place_ours_immeuble.sql');
assert.match(sql,/INSERT INTO public.rue_noeuds_serveur/);
assert.match(sql,/INSERT INTO public.rue_sorties_batiments/);
assert.match(sql,/logements-krasnov-place-ours','\[\"hall\"\]'::jsonb/);
assert.doesNotMatch(sql,/INSERT INTO public.logements_sociaux_historiques/);
console.log('Krasnov : place de l’Ours et immeuble préparé sans baux fictifs : OK');
